/* PLL1 参数（build.ps1 通过 -D 传入；缺省是 480MHz 档）。
 *   VCO = HSE/M × N；SYSCLK = VCO/P；CPU = SYSCLK/D1CPRE；TRACECLK = VCO/R/2
 * 注意：物理 TRACECLK 是 pll1_r_ck 再二分频，所以 R=16 时 VCO 960MHz 得到 30MHz。 */
#ifndef H7_CDC_PLL_M
