/*
 * etm-trace 钩子实现 —— STM32H7B0（Cortex-M7，ETMv4）
 *
 * ⚠️ 本文件**不配置 ETM**，这是刻意的（见 trace_hooks.h 的说明）。
 *    外部工具（OpenOCD / 上位机网页）通过 SWD 完成：
 *      - ETMCR / TRCPRGCTLR / TRCCONFIGR / TRCVICTLR 等 ETMv4 配置
 *      - CSTF(S0) → ETF → TPIU 的 funnel 连接
 *      - PE2~PE6 的 AF0 复用与 TPIU 波特率分频
 *
 * 这里只做：DWT 周期计数器 + 打点 GPIO + 诊断结构体（DTCM 固定地址）。
 */
#include "trace_hooks.h"
#include "stm32h7xx_hal.h"
#include "SEGGER_RTT.h"

#include <stdarg.h>

/* 固定到 DTCM 0x20003000：外部工具可以直接按地址读，不用查符号表。
 * （与 stm32h7b0_spi_trace 的 g_spi_trace 同一约定） */
__attribute__((section(".trace_diag"), used)) volatile trace_diag_t g_trace;

/* DWT / DEMCR（Cortex-M7） */
#define DEMCR      (*(volatile uint32_t *)0xE000EDFCu)
#define DWT_CTRL   (*(volatile uint32_t *)0xE0001000u)
#define DWT_CYCCNT (*(volatile uint32_t *)0xE0001004u)

/* 逻辑分析仪观察脚：PA0（推挽输出，每次打点翻转）。
 * 不接 LA 也不影响运行。 */
#define TRACE_PIN_PORT GPIOA
#define TRACE_PIN      GPIO_PIN_0

static uint32_t s_last_cycles;
static uint8_t s_pin_state;

extern uint32_t g_sysclk_hz;

void trace_hook_init(void)
{
    /* 显式初始化：NOLOAD 段的 C 静态初值不可靠，必须自己写一遍 */
    g_trace.magic = 0x34524354u; /* 'TRC4' */
    g_trace.sysclk_hz = 0;
    g_trace.ready = 0;
    g_trace.loops = 0;
    g_trace.marks = 0;
    g_trace.cyc_last = 0;
    g_trace.cyc_delta = 0;
    g_trace.usb_rx = 0;
    g_trace.usb_tx = 0;
    g_trace.etm_touched = 0;

    /* DWT 周期计数器 */
    DEMCR |= (1u << 24);   /* TRCENA */
    DWT_CYCCNT = 0;
    DWT_CTRL |= (1u << 0); /* CYCCNTENA */

    /* 打点 GPIO：PA0 推挽输出 */
    {
        GPIO_InitTypeDef io = { 0 };
        __HAL_RCC_GPIOA_CLK_ENABLE();
        io.Pin = TRACE_PIN;
        io.Mode = GPIO_MODE_OUTPUT_PP;
        io.Pull = GPIO_NOPULL;
        io.Speed = GPIO_SPEED_FREQ_VERY_HIGH;
        HAL_GPIO_Init(TRACE_PIN_PORT, &io);
        HAL_GPIO_WritePin(TRACE_PIN_PORT, TRACE_PIN, GPIO_PIN_RESET);
    }
}

void trace_hook_entry(void)
{
    /* 只放一个编译期可见的稳定落点，外部工具在这里下硬件断点。
     * 不要写成 static inline，否则会被优化掉。 */
    __asm volatile("nop");
}

void trace_hook_ready(void)
{
    g_trace.sysclk_hz = g_sysclk_hz;
    g_trace.ready = 1u;
}

void trace_hook_mark(void)
{
    uint32_t now = DWT_CYCCNT;

    g_trace.marks++;
    g_trace.cyc_last = now;
    g_trace.cyc_delta = now - s_last_cycles;
    s_last_cycles = now;

    s_pin_state ^= 1u;
    HAL_GPIO_WritePin(TRACE_PIN_PORT, TRACE_PIN,
                      s_pin_state ? GPIO_PIN_SET : GPIO_PIN_RESET);
}

/*
 * 把 ETM/TPIU 显式关掉。故意保留这个函数（而不是干脆不写）：
 *   - 外部工具配置 trace 之前调用它，能得到确定的"全关"初态；
 *   - etm_touched 保持 0，作为"固件没碰 trace 配置"的可验证证据。
 *
 * H7B0 里的地址（Cortex-M7 + CoreSight）：
 *   ETM  0xE0041000  （TRCPRGCTLR@0x004, TRCSTATR@0x00C）
 *   TPIU 0xE0040000  （SPPR@0xF0, FFCR@0x304, ACPR@0x010）
 */
void trace_etm_off(void)
{
    volatile uint32_t *etm_prgctlr = (volatile uint32_t *)0xE0041004u;
    volatile uint32_t *tpiu_sp_pr = (volatile uint32_t *)0xE00400F0u;
    volatile uint32_t *tpiu_ffcr = (volatile uint32_t *)0xE0040304u;

    *etm_prgctlr = 0;              /* ETM 停止 */
    while ((*(volatile uint32_t *)0xE004100Cu & 1u) != 0u) {
        /* 等 TRCSTATR.IDLE = 1 */
    }
    *tpiu_ffcr = 0x00000200u;      /* FFCR: 停止格式化，清 FIFO */
    *tpiu_sp_pr = 0;               /* SPPR: 关闭并行 trace 输出 */

    g_trace.etm_touched = 0;       /* 依然是"没配过" */
}

/*
 * USB 低级初始化 + 中断分发表 —— STM32H743 / USB_OTG_FS（PA11/PA12，内嵌全速 PHY）
 *
 * 型号差异备忘（H743 vs H7B0，两份工程都靠这段代码兼容）：
 *   H743/H750：两个 USB 实例
 *     USB_OTG_FS（= USB2_OTG_FS）@ 0x40080000，中断 OTG_FS_IRQn(=101)
 *     USB_OTG_HS（= USB1_OTG_HS）@ 0x40040000，中断 OTG_HS_IRQn(=77)
 *   H7B0/H7A3/H7B3：只有一个 USB1_OTG_HS @ 0x40040000，中断 OTG_HS_IRQn
 *   → 所以这里的逻辑**按 reg_base 判断**，两个系列都能用；MspInit 里两个实例都判。
 *
 * 阿波罗 H743 注意：板上 USB HOST 与 USB SLAVE 共用 PA11/PA12，需要跳线帽选中 SLAVE；
 * 板上无 ULPI PHY，走不了高速。
 */
#include "stm32h7xx_hal.h"
#include "usbd_core.h"
#include "usb_dwc2_param.h"

#define USB_OTG_HS_BASE_ADDR 0x40040000UL
#define USB_OTG_FS_BASE_ADDR 0x40080000UL

/* 中断分发表（定义在 cherryusb/port/dwc2/usb_glue_st_h7b0.c） */
extern void (*g_usb_dwc2_irq[2])(uint8_t busid);
extern uint8_t g_usb_dwc2_busid[2];

static PCD_HandleTypeDef s_pcd;

void usb_dc_low_level_init(uint8_t busid)
{
    uint32_t base = (uint32_t)g_usbdev_bus[busid].reg_base;

    if (base == USB_OTG_HS_BASE_ADDR) {
        g_usb_dwc2_busid[1] = busid;
        g_usb_dwc2_irq[1] = USBD_IRQHandler;
    } else {
        g_usb_dwc2_busid[0] = busid;
        g_usb_dwc2_irq[0] = USBD_IRQHandler;
    }

    s_pcd.Instance = (USB_OTG_GlobalTypeDef *)base;
    HAL_PCD_MspInit(&s_pcd);
}

void usb_dc_low_level_deinit(uint8_t busid)
{
    uint32_t base = (uint32_t)g_usbdev_bus[busid].reg_base;

    if (base == USB_OTG_HS_BASE_ADDR) {
        g_usb_dwc2_busid[1] = 0;
        g_usb_dwc2_irq[1] = NULL;
    } else {
        g_usb_dwc2_busid[0] = 0;
        g_usb_dwc2_irq[0] = NULL;
    }

    s_pcd.Instance = (USB_OTG_GlobalTypeDef *)base;
    HAL_PCD_MspDeInit(&s_pcd);
}

/* ---------------- HAL_PCD_MspInit / DeInit（ST 惯例的板级钩子） ---------------- */
void HAL_PCD_MspInit(PCD_HandleTypeDef *hpcd)
{
    GPIO_InitTypeDef io = { 0 };

    if (hpcd->Instance == USB_OTG_FS) {
        /* PA11 = DM, PA12 = DP，AF10（H743 上是 OTG_FS 复用） */
        __HAL_RCC_GPIOA_CLK_ENABLE();
        io.Pin = GPIO_PIN_11 | GPIO_PIN_12;
        io.Mode = GPIO_MODE_AF_PP;
        io.Pull = GPIO_NOPULL;
        io.Speed = GPIO_SPEED_FREQ_VERY_HIGH;
#ifdef GPIO_AF10_OTG2_FS
        io.Alternate = GPIO_AF10_OTG2_FS;
#elif defined(GPIO_AF10_OTG_FS)
        io.Alternate = GPIO_AF10_OTG_FS;
#else
        io.Alternate = GPIO_AF10_OTG1_FS;
#endif
        HAL_GPIO_Init(GPIOA, &io);

        __HAL_RCC_USB_OTG_FS_CLK_ENABLE();
        /* 复位：清掉上一次运行/软复位遗留的 DWC2 状态（CherryUSB 自己管协议，不走 HAL_PCD_Init，
         * 所以这一步不会有人替我们做）。 */
        __HAL_RCC_USB_OTG_FS_FORCE_RESET();
        __HAL_RCC_USB_OTG_FS_RELEASE_RESET();

        HAL_NVIC_SetPriority(OTG_FS_IRQn, 3, 0);
        HAL_NVIC_ClearPendingIRQ(OTG_FS_IRQn);
        HAL_NVIC_EnableIRQ(OTG_FS_IRQn);
    } else if (hpcd->Instance == USB_OTG_HS) {
        /* PB14/PB15（或 PA11/PA12 备用）走 HS 口 —— 本工程默认不用，
         * 保留这段是为了将来换 ULPI 高速口时不用重写。 */
        __HAL_RCC_GPIOB_CLK_ENABLE();
        io.Pin = GPIO_PIN_14 | GPIO_PIN_15;
        io.Mode = GPIO_MODE_AF_PP;
        io.Pull = GPIO_NOPULL;
        io.Speed = GPIO_SPEED_FREQ_VERY_HIGH;
        io.Alternate = GPIO_AF12_OTG2_FS; /* H743 上 HS 口的 FS 复用 */
        HAL_GPIO_Init(GPIOB, &io);

        __HAL_RCC_USB1_OTG_HS_CLK_ENABLE();
        __HAL_RCC_USB1_OTG_HS_FORCE_RESET();
        __HAL_RCC_USB1_OTG_HS_RELEASE_RESET();

        HAL_NVIC_SetPriority(OTG_HS_IRQn, 3, 0);
        HAL_NVIC_ClearPendingIRQ(OTG_HS_IRQn);
        HAL_NVIC_EnableIRQ(OTG_HS_IRQn);
    }
}

void HAL_PCD_MspDeInit(PCD_HandleTypeDef *hpcd)
{
    if (hpcd->Instance == USB_OTG_FS) {
        __HAL_RCC_USB_OTG_FS_CLK_DISABLE();
        HAL_NVIC_DisableIRQ(OTG_FS_IRQn);
        HAL_NVIC_ClearPendingIRQ(OTG_FS_IRQn);
        HAL_GPIO_DeInit(GPIOA, GPIO_PIN_11 | GPIO_PIN_12);
    } else if (hpcd->Instance == USB_OTG_HS) {
        __HAL_RCC_USB1_OTG_HS_CLK_DISABLE();
        HAL_NVIC_DisableIRQ(OTG_HS_IRQn);
        HAL_NVIC_ClearPendingIRQ(OTG_HS_IRQn);
        HAL_GPIO_DeInit(GPIOB, GPIO_PIN_14 | GPIO_PIN_15);
    }
}
